        marks: { a:{t:'電鈴', ten:'electric bell',ok:true}, b:{t:'馬達', ten:'motor',ok:true}, c:{t:'磁浮列車', ten:'maglev train',ok:true}, d:{t:'鉛筆', ten:'pencil',ok:false}, e:{t:'木椅', ten:'wooden chair',ok:false}, f:{t:'玻璃杯', ten:'glass cup',ok:false} },
        hint: { s: '會動、會響、要插電的東西,裡面常有電磁鐵!', f: '提示:電鈴靠電磁鐵反覆吸放、馬達靠電流與磁力轉動、磁浮列車靠磁力浮起;鉛筆、木椅、玻璃杯不用電。', en: 'Things that move, buzz, or plug in often have an electromagnet inside!' },
